L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "\226\128\166\226\128\166\227\129\134\227\130\147\227\128\130\227\131\172\227\130\162\227\129\140\227\129\132\227\129\170\227\129\132\233\150\147\227\128\129\228\189\149\229\186\166\227\129\139\229\174\182\227\129\171\230\157\165\227\129\166\227\129\159\227\130\136\227\128\130\227\130\175\227\131\170\227\131\160\227\131\136\227\129\149\227\130\147\227\128\130"
