L4_1.m_Talk_THA = "...\224\184\132\224\185\136\224\184\176 \224\184\149\224\184\173\224\184\153\224\184\132\224\184\184\224\184\147\224\185\132\224\184\161\224\185\136\224\184\173\224\184\162\224\184\185\224\185\136 \224\184\132\224\184\184\224\184\147\224\184\132\224\184\165\224\184\180\224\184\161\224\184\149\224\185\140\224\185\129\224\184\167\224\184\176\224\184\161\224\184\178\224\184\171\224\184\178\224\185\128\224\184\163\224\184\178\224\184\171\224\184\165\224\184\178\224\184\162\224\184\151\224\184\181\224\185\128\224\184\165\224\184\162"
L4_1.m_Talk_VTN = "...\196\144\195\186ng. Trong khi c\225\186\173u \196\145i v\225\186\175ng, \195\180ng Klimt \196\145\195\163 \196\145\225\186\191n ch\225\187\151 ch\195\186ng t\195\180i v\195\160i l\225\186\167n."
